use serde::{Deserialize, Serialize};
use std::collections::HashSet;

/// Result of anti-cheat analysis on benchmark query results.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct AntiCheatResult {
    /// Whether the results passed anti-cheat checks.
    pub passed: bool,
    /// Average Jaccard similarity between sampled pairs of query results.
    pub avg_jaccard_similarity: f64,
    /// Number of unique IDs across all query results.
    pub unique_ids: usize,
    /// Total number of result IDs across all queries.
    pub total_results: usize,
    /// Human-readable summary message.
    pub message: String,
}

/// Compute the Jaccard similarity between two sets of IDs.
///
/// Jaccard(A, B) = |A ∩ B| / |A ∪ B|. Returns 0.0 when both sets are empty.
fn jaccard_similarity(a: &HashSet<u64>, b: &HashSet<u64>) -> f64 {
    let union_size = a.union(b).count();
    if union_size == 0 {
        return 0.0;
    }
    let intersection_size = a.intersection(b).count();
    intersection_size as f64 / union_size as f64
}

/// Detect hardcoded / low-diversity results across queries.
///
/// `results[i]` contains the top-K IDs returned for query `i`.
///
/// Two checks are performed:
/// 1. **Pairwise Jaccard similarity**: sample up to `max_pairs` pairs of queries
///    and compute average Jaccard similarity. If it exceeds `similarity_threshold`
///    (default 0.8), flag as suspicious.
/// 2. **Unique ID count**: count distinct IDs across all results. If the ratio
///    `unique_ids / total_results` is below a minimum diversity ratio, flag.
pub fn detect_hardcoded_results(results: &[Vec<u64>]) -> AntiCheatResult {
    detect_hardcoded_results_with_config(results, 0.8, 500)
}

/// Configurable version of [`detect_hardcoded_results`].
pub fn detect_hardcoded_results_with_config(
    results: &[Vec<u64>],
    similarity_threshold: f64,
    max_pairs: usize,
) -> AntiCheatResult {
    // Handle degenerate cases.
    if results.is_empty() {
        return AntiCheatResult {
            passed: true,
            avg_jaccard_similarity: 0.0,
            unique_ids: 0,
            total_results: 0,
            message: "No results to analyze.".to_string(),
        };
    }

    let all_empty = results.iter().all(|r| r.is_empty());
    if all_empty {
        return AntiCheatResult {
            passed: true,
            avg_jaccard_similarity: 0.0,
            unique_ids: 0,
            total_results: 0,
            message: "All result sets are empty.".to_string(),
        };
    }

    // --- Check 1: Pairwise Jaccard similarity ---
    let sets: Vec<HashSet<u64>> = results
        .iter()
        .map(|ids| ids.iter().copied().collect())
        .collect();

    let n = sets.len();
    let total_possible_pairs = n * (n - 1) / 2;
    let pairs_to_sample = total_possible_pairs.min(max_pairs);

    let avg_similarity = if n < 2 {
        0.0
    } else if pairs_to_sample == total_possible_pairs {
        // Enumerate all pairs.
        let mut sum = 0.0;
        for i in 0..n {
            for j in (i + 1)..n {
                sum += jaccard_similarity(&sets[i], &sets[j]);
            }
        }
        sum / total_possible_pairs as f64
    } else {
        // Deterministic sampling: evenly spaced pairs from the pair index space.
        let step = total_possible_pairs as f64 / pairs_to_sample as f64;
        let mut sum = 0.0;
        for s in 0..pairs_to_sample {
            let pair_idx = (s as f64 * step) as usize;
            let (i, j) = pair_index_to_ij(pair_idx, n);
            sum += jaccard_similarity(&sets[i], &sets[j]);
        }
        sum / pairs_to_sample as f64
    };

    // --- Check 2: Unique ID count ---
    let all_ids: HashSet<u64> = results.iter().flat_map(|ids| ids.iter().copied()).collect();
    let unique_ids = all_ids.len();
    let total_results: usize = results.iter().map(|r| r.len()).sum();

    // --- Verdict ---
    let similarity_flag = avg_similarity > similarity_threshold;
    let passed = !similarity_flag;

    let message = if similarity_flag {
        format!(
            "SUSPICIOUS: Average Jaccard similarity {:.4} exceeds threshold {:.2}. \
             Unique IDs: {}/{} total. Possible hardcoded results detected.",
            avg_similarity, similarity_threshold, unique_ids, total_results
        )
    } else {
        format!(
            "OK: Average Jaccard similarity {:.4} is within threshold {:.2}. \
             Unique IDs: {}/{} total.",
            avg_similarity, similarity_threshold, unique_ids, total_results
        )
    };

    AntiCheatResult {
        passed,
        avg_jaccard_similarity: avg_similarity,
        unique_ids,
        total_results,
        message,
    }
}

/// Convert a linear pair index into (i, j) where i < j < n.
///
/// Pairs are enumerated as: (0,1), (0,2), ..., (0,n-1), (1,2), ..., (n-2,n-1).
fn pair_index_to_ij(idx: usize, n: usize) -> (usize, usize) {
    // Row i starts at cumulative offset: i*n - i*(i+1)/2
    // We solve for i from: idx < i*n - i*(i+1)/2 + (n - i - 1)
    let mut i = 0;
    let mut offset = 0;
    while i < n - 1 {
        let row_len = n - i - 1;
        if idx < offset + row_len {
            let j = i + 1 + (idx - offset);
            return (i, j);
        }
        offset += row_len;
        i += 1;
    }
    // Fallback (should not happen for valid idx).
    (n - 2, n - 1)
}

#[cfg(test)]
mod tests {
    use super::*;

    // --- jaccard_similarity tests ---

    #[test]
    fn test_jaccard_identical_sets() {
        let a: HashSet<u64> = [1, 2, 3].into_iter().collect();
        let sim = jaccard_similarity(&a, &a);
        assert!((sim - 1.0).abs() < f64::EPSILON);
    }

    #[test]
    fn test_jaccard_disjoint_sets() {
        let a: HashSet<u64> = [1, 2, 3].into_iter().collect();
        let b: HashSet<u64> = [4, 5, 6].into_iter().collect();
        let sim = jaccard_similarity(&a, &b);
        assert!(sim.abs() < f64::EPSILON);
    }

    #[test]
    fn test_jaccard_partial_overlap() {
        let a: HashSet<u64> = [1, 2, 3, 4].into_iter().collect();
        let b: HashSet<u64> = [3, 4, 5, 6].into_iter().collect();
        // intersection = {3,4} = 2, union = {1,2,3,4,5,6} = 6
        let sim = jaccard_similarity(&a, &b);
        assert!((sim - 2.0 / 6.0).abs() < 1e-9);
    }

    #[test]
    fn test_jaccard_both_empty() {
        let a: HashSet<u64> = HashSet::new();
        let b: HashSet<u64> = HashSet::new();
        assert_eq!(jaccard_similarity(&a, &b), 0.0);
    }

    // --- pair_index_to_ij tests ---

    #[test]
    fn test_pair_index_mapping() {
        // n=4 → pairs: (0,1),(0,2),(0,3),(1,2),(1,3),(2,3)
        assert_eq!(pair_index_to_ij(0, 4), (0, 1));
        assert_eq!(pair_index_to_ij(1, 4), (0, 2));
        assert_eq!(pair_index_to_ij(2, 4), (0, 3));
        assert_eq!(pair_index_to_ij(3, 4), (1, 2));
        assert_eq!(pair_index_to_ij(4, 4), (1, 3));
        assert_eq!(pair_index_to_ij(5, 4), (2, 3));
    }

    // --- detect_hardcoded_results tests ---

    #[test]
    fn test_all_identical_results_detected_as_cheat() {
        // Every query returns the exact same IDs → Jaccard = 1.0 → flagged.
        let same_ids: Vec<u64> = (0..10).collect();
        let results: Vec<Vec<u64>> = (0..20).map(|_| same_ids.clone()).collect();

        let ac = detect_hardcoded_results(&results);
        assert!(!ac.passed, "Identical results should be flagged");
        assert!((ac.avg_jaccard_similarity - 1.0).abs() < f64::EPSILON);
        assert_eq!(ac.unique_ids, 10);
        assert_eq!(ac.total_results, 200);
    }

    #[test]
    fn test_all_different_results_pass() {
        // Each query returns completely disjoint IDs → Jaccard ≈ 0.
        let results: Vec<Vec<u64>> = (0..20)
            .map(|i| {
                let base = i as u64 * 10;
                (base..base + 10).collect()
            })
            .collect();

        let ac = detect_hardcoded_results(&results);
        assert!(ac.passed, "Disjoint results should pass");
        assert!(ac.avg_jaccard_similarity < 0.01);
        assert_eq!(ac.unique_ids, 200);
        assert_eq!(ac.total_results, 200);
    }

    #[test]
    fn test_partially_similar_results_pass() {
        // Some overlap is normal for nearest-neighbor search.
        // Each query shares ~3 IDs with its neighbor but differs otherwise.
        let results: Vec<Vec<u64>> = (0..20)
            .map(|i| {
                let base = i as u64 * 7; // stride of 7 with 10 IDs → ~3 overlap
                (base..base + 10).collect()
            })
            .collect();

        let ac = detect_hardcoded_results(&results);
        assert!(ac.passed, "Partial overlap should pass");
        assert!(ac.avg_jaccard_similarity < 0.8);
    }

    #[test]
    fn test_empty_results_handled_gracefully() {
        let ac = detect_hardcoded_results(&[]);
        assert!(ac.passed);

use serde::{Deserialize, Serialize};
use std::collections::HashSet;
use std::path::Path;

use crate::runner::QueryResult;

/// A single ground truth entry: the pre-computed nearest neighbors for a query.
#[derive(Debug, Clone, Deserialize)]
pub struct GroundTruthEntry {
    pub query_id: usize,
    pub neighbors: Vec<u64>, // Top-100 nearest neighbor IDs
}

/// Complete benchmark result with all metrics.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct BenchmarkResult {
    pub qps: f64,
    pub total_queries: usize,
    pub duration_secs: f64,
    pub avg_latency_ms: f64,
    pub p50_latency_ms: f64,
    pub p95_latency_ms: f64,
    pub p99_latency_ms: f64,
    pub recall: f64,
    pub recall_threshold: f64,
    pub recall_passed: bool,
    pub concurrency: usize,
}

/// Calculate queries per second.
pub fn calculate_qps(total_queries: usize, duration_secs: f64) -> f64 {
    if duration_secs <= 0.0 {
        return 0.0;
    }
    total_queries as f64 / duration_secs
}

/// Calculate the p-th percentile from a mutable slice of latencies.
///
/// Sorts the slice in place and returns the value at the given percentile.
/// `p` should be in [0.0, 100.0].
pub fn calculate_percentile(latencies: &mut [f64], p: f64) -> f64 {
    if latencies.is_empty() {
        return 0.0;
    }
    latencies.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let rank = (p / 100.0) * (latencies.len() - 1) as f64;
    let lower = rank.floor() as usize;
    let upper = rank.ceil() as usize;
    if lower == upper {
        latencies[lower]
    } else {
        let frac = rank - lower as f64;
        latencies[lower] * (1.0 - frac) + latencies[upper] * frac
    }
}

/// Calculate average recall across all queries.
///
/// For each query, computes the intersection of the model's top-10 result IDs
/// with the ground truth top-10 IDs, divided by 10. Returns the average across
/// all queries.
pub fn calculate_recall(
    query_results: &[QueryResult],
    ground_truth: &[GroundTruthEntry],
) -> f64 {
    if query_results.is_empty() || ground_truth.is_empty() {
        return 0.0;
    }

    // Build a lookup from query_id -> ground truth neighbors
    let gt_map: std::collections::HashMap<usize, &Vec<u64>> = ground_truth
        .iter()
        .map(|gt| (gt.query_id, &gt.neighbors))
        .collect();

    let total_recall: f64 = query_results
        .iter()
        .filter_map(|qr| {
            let gt_neighbors = gt_map.get(&qr.query_index)?;
            let gt_top10: HashSet<u64> = gt_neighbors.iter().take(10).copied().collect();
            let model_top10: HashSet<u64> = qr.results.iter().take(10).map(|r| r.id).collect();
            let intersection = model_top10.intersection(&gt_top10).count();
            Some(intersection as f64 / 10.0)
        })
        .sum();

    let matched_count = query_results
        .iter()
        .filter(|qr| gt_map.contains_key(&qr.query_index))
        .count();

    if matched_count == 0 {
        return 0.0;
    }

    total_recall / matched_count as f64
}

/// Combine all calculations into a single BenchmarkResult.
pub fn compute_benchmark_result(
    query_results: &[QueryResult],
    ground_truth: &[GroundTruthEntry],
    duration_secs: f64,
    concurrency: usize,
    recall_threshold: f64,
) -> BenchmarkResult {
    let total_queries = query_results.len();
    let qps = calculate_qps(total_queries, duration_secs);

    let mut latencies: Vec<f64> = query_results.iter().map(|qr| qr.latency_ms).collect();
    let avg_latency_ms = if latencies.is_empty() {
        0.0
    } else {
        latencies.iter().sum::<f64>() / latencies.len() as f64
    };

    let p50 = calculate_percentile(&mut latencies, 50.0);
    let p95 = calculate_percentile(&mut latencies, 95.0);
    let p99 = calculate_percentile(&mut latencies, 99.0);

    let recall = calculate_recall(query_results, ground_truth);
    let recall_passed = recall >= recall_threshold;

    BenchmarkResult {
        qps,
        total_queries,
        duration_secs,
        avg_latency_ms,
        p50_latency_ms: p50,
        p95_latency_ms: p95,
        p99_latency_ms: p99,
        recall,
        recall_threshold,
        recall_passed,
        concurrency,
    }
}

/// Load ground truth entries from a JSON file.
pub async fn load_ground_truth(
    path: &str,
) -> Result<Vec<GroundTruthEntry>, Box<dyn std::error::Error>> {
    let path = Path::new(path);
    let content = tokio::fs::read_to_string(path).await?;
    let entries: Vec<GroundTruthEntry> = serde_json::from_str(&content)?;
    Ok(entries)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::runner::SearchResult;

    // --- QPS tests ---

    #[test]
    fn test_qps_basic() {
        let qps = calculate_qps(1000, 2.0);
        assert!((qps - 500.0).abs() < f64::EPSILON);
    }

    #[test]
    fn test_qps_zero_duration() {
        assert_eq!(calculate_qps(100, 0.0), 0.0);
    }

    #[test]
    fn test_qps_negative_duration() {
        assert_eq!(calculate_qps(100, -1.0), 0.0);
    }

    #[test]
    fn test_qps_zero_queries() {
        assert_eq!(calculate_qps(0, 5.0), 0.0);
    }

    // --- Percentile tests ---

    #[test]
    fn test_percentile_single_value() {
        let mut data = vec![42.0];
        assert!((calculate_percentile(&mut data, 50.0) - 42.0).abs() < f64::EPSILON);
        assert!((calculate_percentile(&mut data, 99.0) - 42.0).abs() < f64::EPSILON);
    }

    #[test]
    fn test_percentile_empty() {
        let mut data: Vec<f64> = vec![];
        assert_eq!(calculate_percentile(&mut data, 50.0), 0.0);
    }

    #[test]
    fn test_percentile_known_values() {
        // 10 values: 1..=10
        let mut data: Vec<f64> = (1..=10).map(|x| x as f64).collect();
        let p50 = calculate_percentile(&mut data, 50.0);
        // rank = 0.5 * 9 = 4.5 → interpolate between data[4]=5 and data[5]=6 → 5.5
        assert!((p50 - 5.5).abs() < 1e-9);

        let p0 = calculate_percentile(&mut data, 0.0);
        assert!((p0 - 1.0).abs() < 1e-9);

        let p100 = calculate_percentile(&mut data, 100.0);
        assert!((p100 - 10.0).abs() < 1e-9);
    }

    #[test]
    fn test_percentile_ordering() {
        let mut data: Vec<f64> = (1..=100).map(|x| x as f64).collect();
        let p50 = calculate_percentile(&mut data, 50.0);
        let p95 = calculate_percentile(&mut data, 95.0);
        let p99 = calculate_percentile(&mut data, 99.0);
        assert!(p50 <= p95);
        assert!(p95 <= p99);
    }

    // --- Recall tests ---

    fn make_query_result(query_index: usize, ids: Vec<u64>) -> QueryResult {
        QueryResult {
            query_index,
            results: ids
                .into_iter()
                .map(|id| SearchResult {
                    id,
                    distance: 0.0,
                })
                .collect(),
            latency_ms: 1.0,
        }
    }

    fn make_gt(query_id: usize, neighbors: Vec<u64>) -> GroundTruthEntry {
        GroundTruthEntry {
            query_id,
            neighbors,
        }
    }

    #[test]
    fn test_recall_perfect() {
        let ids: Vec<u64> = (0..10).collect();
        let qr = vec![make_query_result(0, ids.clone())];
        let gt = vec![make_gt(0, ids)];
        let recall = calculate_recall(&qr, &gt);
        assert!((recall - 1.0).abs() < f64::EPSILON);
    }

    #[test]
    fn test_recall_zero() {
        let qr = vec![make_query_result(0, (0..10).collect())];
        let gt = vec![make_gt(0, (100..110).collect())];
        let recall = calculate_recall(&qr, &gt);
        assert!(recall.abs() < f64::EPSILON);
    }

    #[test]
    fn test_recall_partial() {
        // 5 out of 10 match
        let model_ids: Vec<u64> = (0..10).collect();
        let gt_ids: Vec<u64> = (5..15).collect();
        let qr = vec![make_query_result(0, model_ids)];
        let gt = vec![make_gt(0, gt_ids)];
        let recall = calculate_recall(&qr, &gt);
        assert!((recall - 0.5).abs() < f64::EPSILON);
    }

    #[test]
    fn test_recall_empty_inputs() {
        assert_eq!(calculate_recall(&[], &[]), 0.0);
        let gt = vec![make_gt(0, (0..10).collect())];
        assert_eq!(calculate_recall(&[], &gt), 0.0);
        let qr = vec![make_query_result(0, (0..10).collect())];
        assert_eq!(calculate_recall(&qr, &[]), 0.0);
    }

    #[test]
    fn test_recall_multiple_queries() {
        let qr = vec![
            make_query_result(0, (0..10).collect()),  // perfect
            make_query_result(1, (100..110).collect()), // zero
        ];
        let gt = vec![
            make_gt(0, (0..10).collect()),
            make_gt(1, (0..10).collect()),
        ];
        let recall = calculate_recall(&qr, &gt);
        assert!((recall - 0.5).abs() < f64::EPSILON);
    }

    // --- compute_benchmark_result test ---

    #[test]
    fn test_compute_benchmark_result() {
        let ids: Vec<u64> = (0..10).collect();
        let qr = vec![
            QueryResult {
                query_index: 0,
                results: ids.iter().map(|&id| SearchResult { id, distance: 0.0 }).collect(),
                latency_ms: 10.0,
            },
            QueryResult {
                query_index: 1,
                results: ids.iter().map(|&id| SearchResult { id, distance: 0.0 }).collect(),
                latency_ms: 20.0,
            },
        ];
        let gt = vec![
            make_gt(0, ids.clone()),
            make_gt(1, ids.clone()),
        ];

        let result = compute_benchmark_result(&qr, &gt, 1.0, 4, 0.95);

        assert!((result.qps - 2.0).abs() < f64::EPSILON);
        assert_eq!(result.total_queries, 2);
        assert!((result.duration_secs - 1.0).abs() < f64::EPSILON);
        assert!((result.avg_latency_ms - 15.0).abs() < f64::EPSILON);
        assert!((result.recall - 1.0).abs() < f64::EPSILON);
        assert!(result.recall_passed);
        assert_eq!(result.concurrency, 4);
    }

    // --- JSON round-trip test ---

    #[test]
    fn test_benchmark_result_json_roundtrip() {
        let result = BenchmarkResult {
            qps: 1234.5,
            total_queries: 10000,
            duration_secs: 8.1,
            avg_latency_ms: 3.2,
            p50_latency_ms: 2.5,
            p95_latency_ms: 8.0,
            p99_latency_ms: 15.0,
            recall: 0.97,
            recall_threshold: 0.95,
            recall_passed: true,
            concurrency: 4,
        };

        let json = serde_json::to_string(&result).unwrap();
        let deserialized: BenchmarkResult = serde_json::from_str(&json).unwrap();
        assert_eq!(result, deserialized);
    }

    // --- Ground truth deserialization test ---

    #[test]
    fn test_ground_truth_deserialize() {
        let json = r#"[{"query_id": 0, "neighbors": [1, 2, 3]}]"#;
        let entries: Vec<GroundTruthEntry> = serde_json::from_str(json).unwrap();
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].query_id, 0);
        assert_eq!(entries[0].neighbors, vec![1, 2, 3]);
    }
}

